mapper.select:
SELECT DISTINCT A.PORTFOLIO_ID id, A.PORTFOLIO_NAME text FROM PTL_PORTFOLIO A LEFT JOIN PTL_SEC_ACCT PSA ON A.PORTFOLIO_ID = PSA.PORTFOLIO_ID LEFT JOIN PTL_CAPACCT_INFO PCI ON PCI.PORTFOLIO_ID = A.PORTFOLIO_ID WHERE A.INVEST_YESORNO = 'Y' AND A.PORTFOLIO_ID != #{invTransPortf,jdbcType=VARCHAR} AND A.MDATE >=TO_DATE(#{tradeDate},'yyyy-MM-dd') AND A.VDATE <=TO_DATE(#{tradeDate},'yyyy-MM-dd')
AND PSA.ACCT_NO=#{secAcctId,jdbcType=VARCHAR}
AND PCI.ACCT_NO in (SELECT DISTINCT B.ACCT_NO FROM PTL_CAPACCT_INFO B WHERE B.PORTFOLIO_ID = #{invTransPortf} AND B.ACCT_TYPE = #{capacctType} AND B.CCY = #{ccy})
AND A.PORTFOLIO_ID = #{initValue}
AND ( A.PORTFOLIO_ID LIKE CONCAT('%', CONCAT(#{search}, '%')) or A.PORTFOLIO_NAME LIKE CONCAT('%', CONCAT(#{search}, '%')) )

SELECT fdp.PLEDGE_FINPROD_ID AS pledgeFinprodId, fp.FINPROD_ABBR AS finprodAbbr, NVL(fdp.PLEDGE_NUMBER, 0) * 100 pledgePrin, NVL(fdp.PLEDGE_RATIO,0) * 100 pledgeRatio, (NVL(table1.AMOUNT,0) - NVL(table2.AMOUNT,0) + NVL(table3.AMOUNT,0))*100 as prdPledgePrin FROM FIN_DEAL_PLEDGE fdp LEFT JOIN TRD_PRODUCT_DEAL tpd ON fdp.FINPROD_ID = tpd.TRADE_ID LEFT JOIN FIN_PRODUCT fp ON fdp.PLEDGE_FINPROD_ID = fp.FINPROD_ID LEFT JOIN ( SELECT psp.FINPROD_ID,sum(psp.AMOUNT) AS AMOUNT FROM PTL_SEC_POSITION psp WHERE psp.PORTFOLIO_ID = #{portfolioId,jdbcType=VARCHAR}
AND psp.SEC_ACCT_ID = #{secAcctId,jdbcType=VARCHAR}
AND psp.SEC_ACCT_ID = #{chlId,jdbcType=VARCHAR}
AND psp.HODING_TYPE IN ('01','03','05','08')
AND psp.CDATE = TO_DATE(#{tradeDate},'yyyy-MM-dd')
GROUP BY psp.FINPROD_ID )table1 ON table1.FINPROD_ID=fdp.PLEDGE_FINPROD_ID LEFT JOIN ( SELECT psp.FINPROD_ID,sum(psp.AMOUNT) AS AMOUNT FROM PTL_SEC_POSITION psp WHERE psp.PORTFOLIO_ID = #{portfolioId,jdbcType=VARCHAR}
AND psp.SEC_ACCT_ID = #{secAcctId,jdbcType=VARCHAR}
AND psp.SEC_ACCT_ID = #{chlId,jdbcType=VARCHAR}
AND psp.HODING_TYPE in('04','06','11')
AND psp.CDATE = TO_DATE(#{tradeDate},'yyyy-MM-dd')
GROUP BY psp.FINPROD_ID )table2 ON table2.FINPROD_ID=fdp.PLEDGE_FINPROD_ID LEFT JOIN ( SELECT SUM(DECODE(PSP.HODING_TYPE, '12', -1*psp.AMOUNT, psp.amount)) AMOUNT, psp.finprod_id FROM PTL_SEC_POSITION_FLOW PSP INNER JOIN FIN_PRODUCT T ON PSP.FINPROD_ID = T.FINPROD_ID AND T.FINPROD_TYPE2 = 'F01' AND psp.PORTFOLIO_ID = #{portfolioId,jdbcType=VARCHAR} AND psp.CDATE <= TO_DATE(#{tradeDate},'yyyy-MM-dd') AND PSP.HODING_TYPE IN ('01','12') AND PSP.SEC_ACCT_ID = #{secAcctId,jdbcType=VARCHAR} AND NOT EXISTS ( SELECT 1 FROM PTL_SEC_POSITION_FLOW PSP1 WHERE PSP1.portfolio_id = psp.portfolio_id AND PSP1.sec_acct_id = psp.sec_acct_id AND PSP1.finprod_id = psp.finprod_id AND PSP1.CDATE <= TO_DATE(#{tradeDate},'yyyy-MM-dd') AND PSP1.CDATE > psp.CDATE AND PSP1.branch = psp.branch AND PSP1.inv_aim = psp.inv_aim AND PSP1.hoding_type = psp.hoding_type AND PSP1.ccy = psp.ccy) GROUP BY PSP.finprod_id )table3 ON table3.FINPROD_ID=fdp.PLEDGE_FINPROD_ID WHERE fdp.FINPROD_ID = #{splitTradeId,jdbcType=VARCHAR} and tpd.IS_CANCEL='N'
